def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    out = [row[:] for row in grid]
    # Join marks aligned in a row or column, without overwriting marks.
    for r in range(h):
        cols = [c for c, v in enumerate(grid[r]) if v != bg]
        if len(cols) >= 2:
            for c in range(cols[0] + 1, cols[-1]):
                if grid[r][c] == bg:
                    out[r][c] = 3
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] != bg]
        if len(rows) >= 2:
            for r in range(rows[0] + 1, rows[-1]):
                if grid[r][c] == bg:
                    out[r][c] = 3
    return out
